    for r in range(3):
        for c in range(w):
            if out[r][c] == 0:
                marks = [grid[3*b+r][c] for b in (1, 2, 3)]
                for color in (4, 8, 2):
                    if color in marks:
                        out[r][c] = color
                        break
    return out
